BEGIN TRANSACTION;
CREATE TABLE document_properties ( key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
CREATE TABLE entities ( id INTEGER PRIMARY KEY, type_id TEXT NOT NULL, layer TEXT, has_color_override INTEGER, color_r REAL, color_g REAL, color_b REAL, params TEXT);
CREATE TABLE entity_properties ( entity_id INTEGER NOT NULL, key TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (entity_id, key), FOREIGN KEY (entity_id) REFERENCES entities(id) ON DELETE CASCADE);
CREATE TABLE furniture ( id INTEGER PRIMARY KEY, sheet_id INTEGER NOT NULL, nature TEXT NOT NULL, template_id TEXT NOT NULL, zone_x REAL, zone_y REAL, zone_w REAL, zone_h REAL, FOREIGN KEY (sheet_id) REFERENCES sheets(id) ON DELETE CASCADE);
CREATE TABLE furniture_fields ( furniture_id INTEGER NOT NULL, slot INTEGER NOT NULL, role TEXT NOT NULL, label TEXT NOT NULL, key TEXT NOT NULL, format TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (furniture_id, slot), FOREIGN KEY (furniture_id) REFERENCES furniture(id) ON DELETE CASCADE);
CREATE TABLE layers ( name TEXT PRIMARY KEY, color_r REAL, color_g REAL, color_b REAL, line_weight REAL, visible INTEGER, locked INTEGER, line_type INTEGER);
CREATE TABLE sheet_views ( sheet_id INTEGER NOT NULL, idx INTEGER NOT NULL, src_minx REAL, src_miny REAL, src_maxx REAL, src_maxy REAL, scale REAL, paper_x REAL, paper_y REAL, paper_w REAL, paper_h REAL, PRIMARY KEY (sheet_id, idx), FOREIGN KEY (sheet_id) REFERENCES sheets(id) ON DELETE CASCADE);
CREATE TABLE sheets ( id INTEGER PRIMARY KEY, title TEXT NOT NULL, format_token TEXT NOT NULL, orientation_token TEXT NOT NULL, margin_top REAL, margin_bottom REAL, margin_left REAL, margin_right REAL);
COMMIT;
